":[{"ready":true,"enabled":false,"provider":"manual_eft","maintenance":false},{"ready":true,"enabled":false,"provider":"manual_payshap","maintenance":false},{"ready":false,"enabled":false,"provider":"ozow","maintenance":true},{"ready":true,"enabled":false,"provider":"payfast","maintenance":false}],"project":"eyhmarmekioovcjibcbr","projectName":"officebites-staging","scope":"read-only metadata; not approval"}$eft_baseline$::jsonb;actual jsonb;k text;BEGIN
